WITH base AS (SELECT * FROM departments WHERE budget > 3984000 AND (budget <= 2766000 OR budget >= 2924000)), agg AS (SELECT CASE WHEN budget >= 4360000 THEN 'high' WHEN budget >= 728000 THEN 'mid' ELSE 'low' END AS budget_bucket, MIN(budget) AS min_budget, SUM(CASE WHEN dept_name = 'Finance' THEN 1 ELSE 0 END) AS finance_count FROM base GROUP BY CASE WHEN budget >= 4360000 THEN 'high' WHEN budget >= 728000 THEN 'mid' ELSE 'low' END) SELECT budget_bucket, min_budget, finance_count FROM agg ORDER BY budget_bucket
